sysauto_script.script:
(function() {
    try {
        gs.info('Starting daily leave summary generation...');

        // Get yesterday's date
        var yesterday = new GlideDateTime();
        yesterday.addDaysLocalTime(-1);
        var targetDate = yesterday.getDate().toString();

        // Query leave records for yesterday
        var leaveRecords = new GlideRecord('x_1973840_leave_per_leave');
        leaveRecords.addQuery('leave_date_start', '<=', targetDate);
        leaveRecords.addQuery('leave_date_end', '>=', targetDate);
        leaveRecords.addQuery('active', true);
        leaveRecords.query();

        var summaryCount = 0;

        gs.info('Found ' + leaveRecords.getRowCount() + ' leave records for date: ' + targetDate);

        while (leaveRecords.next()) {
            try {
                // Get employee information
                var employee = leaveRecords.opened_by.getRefRecord();
                var employeeName = employee ? employee.getDisplayValue() : 'Unknown Employee';

                // Map leave type from choice field
                var leaveTypeDisplay = leaveRecords.leave_type.getDisplayValue() || 'Unknown Type';

                // Map approval status  
                var approvalStatus = leaveRecords.approval.getDisplayValue() || 'Not Set';

                gs.info('Processing record: ' + leaveRecords.number + ' for employee: ' + employeeName);

                // Check if summary already exists for this record and date
                var existingSummary = new GlideRecord('x_1973840_leave_daily_leave_summary');
                existingSummary.addQuery('summary_date', targetDate);
                existingSummary.addQuery('original_record_id', leaveRecords.sys_id.toString());
                existingSummary.query();

                if (!existingSummary.hasNext()) {
                    // Create new summary record
                    var summary = new GlideRecord('x_1973840_leave_daily_leave_summary');
                    summary.initialize();

                    summary.summary_date = targetDate;
                    summary.employee_name = employeeName;
                    summary.employee_id = leaveRecords.opened_by.toString();
                    summary.leave_start_date = leaveRecords.leave_date_start.toString();
                    summary.leave_end_date = leaveRecords.leave_date_end.toString();
                    summary.leave_start_time = leaveRecords.leave_time_start.getDisplayValue() || '';
                    summary.leave_end_time = leaveRecords.leave_time_end.getDisplayValue() || '';
                    summary.leave_reason = leaveRecords.short_description.toString();
                    summary.leave_type = leaveTypeDisplay;
                    summary.approval_status = approvalStatus;
                    summary.original_record_id = leaveRecords.sys_id.toString();

                    var insertedId = summary.insert();
                    if (insertedId) {
                        summaryCount++;
                        gs.info('Created summary record for employee: ' + employeeName + 
                               ', Record ID: ' + insertedId + ', Leave: ' + leaveRecords.short_description);
                    } else {
                        gs.warn('Failed to create summary for leave record: ' + leaveRecords.number);
                    }
                } else {
                    gs.info('Summary already exists for leave record: ' + leaveRecords.number + 
                           ' on date: ' + targetDate);
                }

            } catch (recordError) {
                gs.error('Error processing leave record ' + leaveRecords.number + 
                        ': ' + recordError.message);
            }
        }

        gs.info('Daily leave summary generation completed for ' + targetDate + '. Created ' + summaryCount + 
               ' new summary records.');

    } catch (globalError) {
        gs.error('Error in daily leave summary script: ' + globalError.message);
    }
})();
